function linearGradCtx(ctx,c,box,factor=1){const{a,b}=pointsFor(c,box),dx=b.x-a.x||.1;const g=ctx.createLinearGradient(a.x,a.y,a.x+dx,b.y);for(const s of stopsFor(c))g.addColorStop(clamp(s.pos/100,0,1),rgbaOf(s.color,factor));return g;}
function foldStroke(ctx,tint){const x1=foldGradientDef.x1,y1=foldGradientDef.y1,x2=foldGradientDef.x2,y2=foldGradientDef.y2;const g=ctx.createLinearGradient(x1,y1,x2,y2);for(const s of foldGradientDef.stops){const col=s.color==='white'&&tint?rgbaOf(tint,1,s.opacity):rgbaOf(s.color,1,s.opacity);g.addColorStop(s.offset,col);}return g;}
function radialGrad(ctx,s,c,steps){const g=ctx.createRadialGradient(0,0,0,0,0,1);const v=rgb(c).map(t=>Math.round(t*255));for(let k=0;k<steps;k++){const t=k/steps;g.addColorStop(t,'rgba('+v[0]+','+v[1]+','+v[2]+','+(s.opacity*Math.exp(-4.5*t*t)).toFixed(4)+')');}g.addColorStop(1,'rgba('+v[0]+','+v[1]+','+v[2]+',0)');return g;}
function drawSpot(ctx,s,c,x,y,spread,path,steps,fieldFill){const sx=s.rx*spread,sy=s.ry*spread;if(sx<=0||sy<=0)return;ctx.save();ctx.translate(x,y);ctx.scale(sx,sy);ctx.fillStyle=radialGrad(ctx,s,c,steps);if(fieldFill){ctx.fillRect(-1,-1,2,2);}else{const inv=new DOMMatrix([1/sx,0,0,1/sy,-x/sx,-y/sy]);const unit=new Path2D();unit.addPath(path,inv);ctx.fill(unit);}ctx.restore();}
