async function renderK(){try{drawK(isolate&&target!=='background'?[target]:[0,1,2],interacting?6:25);readyK=true;scheduleThumbs();}catch(error){toast('K 预览暂时无法更新，请重试。');}}
async function renderBackground(){if(bgBusy){bgPending=true;return;}bgBusy=true;try{const revision=++bgRevision,size=1024,svg=backgroundBaseSVG(size),key=size+'|'+svg;if(!baseCache.has(key)){if(baseCache.size>12)baseCache.clear();baseCache.set(key,loadImageSVG(svg));}const image=await baseCache.get(key);if(revision!==bgRevision&&!interacting)return;const ctx=$('background-preview').getContext('2d');ctx.clearRect(0,0,1024,1024);ctx.drawImage(image,0,0,1024,1024);ctx.drawImage(paintRaster(),0,0);readyBG=true;scheduleThumbs();}finally{bgBusy=false;if(bgPending){bgPending=false;renderBackground().catch(()=>{});}}}
