['r','g','b'].forEach(channel=>{const el=$('rgb-'+channel);el.addEventListener('input',()=>{const vals=['r','g','b'].map(c=>$('rgb-'+c).value);if(vals.some(v=>v===''||!Number.isFinite(Number(v))||Number(v)<0||Number(v)>255)){$('color-error').textContent='R、G、B 都需要在 0–255 之间。';$('color-error').className='input-hint error';return;}setColor(hex(vals.map(v=>Math.round(Number(v))/255)));});el.addEventListener('change',()=>{if(el.value==='')syncColor();else{el.value=Math.round(num(el.value,0,255));const values=['r','g','b'].map(c=>num($('rgb-'+c).value,0,255));setColor(hex(values.map(v=>v/255)));}});});
