const artboard=$('artboard');
function pointer(e){const r=artboard.getBoundingClientRect();return{x:clamp((e.clientX-r.left)/r.width*1024,0,1024),y:clamp((e.clientY-r.top)/r.height*1024,0,1024)};}
function rememberPaint(before){paintUndo.push(before);if(paintUndo.length>25)paintUndo.shift();paintRedo=[];}
artboard.addEventListener('pointerdown',e=>{if(e.button!==0)return;const p=pointer(e);if(target==='background'&&paintEnabled){if(state.background.strokes.length>=80){toast('已达到 80 笔，请先保存配色或清理部分笔触。');return;}paintBefore=copy(state.background.strokes);state.background.strokes.push({color:state.background.brushColor,size:state.background.size,opacity:state.background.opacity,erase:state.background.erase,points:[p]});activeDrag={type:'paint',id:e.pointerId};}else{const handle=e.target.closest('[data-handle]');if(!handle)return;activeDrag={type:handle.dataset.handle,id:e.pointerId};if(activeDrag.type.startsWith('stop-')){selected='stop';selectedStop=Number(activeDrag.type.slice(5));syncColor();}}try{artboard.setPointerCapture(e.pointerId)}catch(_){};e.preventDefault();});
artboard.addEventListener('pointermove',e=>{if(!activeDrag||e.pointerId!==activeDrag.id)return;markInteracting();const p=pointer(e),c=settingsFor(),box=currentBox();if(activeDrag.type==='paint'){const points=state.background.strokes.at(-1).points,last=points.at(-1);if(Math.hypot(last.x-p.x,last.y-p.y)>3&&points.length<1500)points.push(p);schedule(false,true);}else{if(activeDrag.type.startsWith('stop-'))c.stops[selectedStop].pos=Math.round(project(p,c,box)*100);else c[activeDrag.type]={x:Math.round(clamp((p.x-box.x)/box.width*100,0,100)),y:Math.round(clamp((p.y-box.y)/box.height*100,0,100))};schedule(target!=='background',target==='background');}});
function finishPointer(e){if(!activeDrag||e.pointerId!==activeDrag.id)return;if(activeDrag.type==='paint'){rememberPaint(paintBefore);paintBefore=null;}activeDrag=null;if(artboard.hasPointerCapture(e.pointerId))artboard.releasePointerCapture(e.pointerId);renderSettings();syncColor();schedule(target!=='background',target==='background');}
artboard.addEventListener('pointerup',finishPointer);artboard.addEventListener('pointercancel',finishPointer);
$('handles').addEventListener('keydown',e=>{const handle=e.target.closest('[data-handle]');if(!handle||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const c=settingsFor(),type=handle.dataset.handle,delta=(e.shiftKey?10:1)*(['ArrowLeft','ArrowUp'].includes(e.key)?-1:1);if(type.startsWith('stop-')){selectedStop=Number(type.slice(5));c.stops[selectedStop].pos=clamp(c.stops[selectedStop].pos+delta,0,100);}else{const axis=['ArrowUp','ArrowDown'].includes(e.key)?'y':'x';c[type][axis]=clamp(c[type][axis]+delta,0,100);}schedule(target!=='background',target==='background');});
$('secondary-settings').addEventListener('click',e=>{const id=e.target.closest('button')?.id,b=state.background;if(id==='paint-toggle'){paintEnabled=!paintEnabled;selected='brush';renderSettings();syncColor();}else if(id==='paint-undo'&&paintUndo.length){paintRedo.push(copy(b.strokes));b.strokes=paintUndo.pop();renderSettings();schedule(false,true);}else if(id==='paint-redo'&&paintRedo.length){paintUndo.push(copy(b.strokes));b.strokes=paintRedo.pop();renderSettings();schedule(false,true);}else if(id==='paint-clear'&&b.strokes.length){rememberPaint(copy(b.strokes));b.strokes=[];renderSettings();schedule(false,true);}});
function download(data,name,type='application/octet-stream'){const blob=data instanceof Blob?data:new Blob([data],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();const previous=$('last-download');if(previous){URL.revokeObjectURL(previous.href);previous.remove();}const retry=document.createElement('a');retry.id='last-download';retry.href=url;retry.download=name;retry.textContent='再次下载 '+name;retry.setAttribute('aria-label','再次下载 '+name);document.querySelector('.stage-footer').appendChild(retry);}
const crcTable=Array.from({length:256},(_,i)=>{let c=i;for(let j=0;j<8;j++)c=c&1?0xedb88320^(c>>>1):c>>>1;return c>>>0});
function crc32(bytes){let c=0xffffffff;for(const b of bytes)c=crcTable[(c^b)&255]^(c>>>8);return(c^0xffffffff)>>>0}
function makeZip(files){const enc=new TextEncoder(),local=[],central=[];let offset=0;const put=(view,pos,value,short=false)=>short?view.setUint16(pos,value,true):view.setUint32(pos,value,true);for(const file of files){const name=enc.encode(file.name),body=typeof file.data==='string'?enc.encode(file.data):file.data,crc=crc32(body);const head=new Uint8Array(30+name.length),v=new DataView(head.buffer);put(v,0,0x04034b50);put(v,4,20,true);put(v,6,0x800,true);put(v,8,0,true);put(v,12,33,true);put(v,14,crc);put(v,18,body.length);put(v,22,body.length);put(v,26,name.length,true);head.set(name,30);local.push(head,body);const ch=new Uint8Array(46+name.length),cv=new DataView(ch.buffer);put(cv,0,0x02014b50);put(cv,4,20,true);put(cv,6,20,true);put(cv,8,0x800,true);put(cv,10,0,true);put(cv,14,33,true);put(cv,16,crc);put(cv,20,body.length);put(cv,24,body.length);put(cv,28,name.length,true);put(cv,42,offset);ch.set(name,46);central.push(ch);offset+=head.length+body.length}const centralSize=central.reduce((n,a)=>n+a.length,0),end=new Uint8Array(22),ev=new DataView(end.buffer);put(ev,0,0x06054b50);put(ev,8,files.length,true);put(ev,10,files.length,true);put(ev,12,centralSize);put(ev,16,offset);return new Blob([...local,...central,end],{type:'application/zip'})}
function decode64(value){const raw=atob(value);return Uint8Array.from(raw,c=>c.charCodeAt(0))}

