async function canvasBlob(canvas){return new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(Error('PNG 导出失败')),'image/png'));}
async function backgroundCanvasFull(){const svg=backgroundBaseSVG(1024),key='1024|'+svg;let image;if(baseCache.has(key)){image=await baseCache.get(key);}else{const p=loadImageSVG(svg);baseCache.set(key,p);image=await p;}const canvas=createCanvas(),ctx=canvas.getContext('2d');ctx.drawImage(image,0,0,1024,1024);ctx.drawImage(paintRaster(),0,0);return canvas;}
async function fullComposite(){const image=await loadImageSVG(makeKSVG()),canvas=createCanvas(),ctx=canvas.getContext('2d');ctx.drawImage(await backgroundCanvasFull(),0,0);ctx.drawImage(image,0,0,1024,1024);await grainReady;if(state.detail&&grain.naturalWidth)ctx.drawImage(surfaceDetail(),0,0);return canvas;}
function backgroundSVGWithPaint(){const base=backgroundBaseSVG();if(!state.background.strokes.length)return base;return base.replace('</svg>',`<image width="1024" height="1024" href="${paintRaster().toDataURL('image/png')}"/></svg>`);}
async function doExport(type){try{if(type==='svg'){download(makeKSVG(),'KyFold_K.svg','image/svg+xml');toast('已导出完整透明 K，三片仍为矢量路径。');}else if(type==='png'){download(await canvasBlob(await fullComposite()),'KyFold_Icon_1024.png');toast('已导出 1024 × 1024 完整 PNG。');}else if(type==='background'){download(await canvasBlob(await backgroundCanvasFull()),'KyFold_Background.png');toast('已导出独立背景，包含模糊画笔。');}else if(type==='zip'){toast('正在打包当前配色…');const bg=await canvasBlob(await backgroundCanvasFull()),full=await canvasBlob(await fullComposite()),files=[{name:'00_Background.png',data:new Uint8Array(await bg.arrayBuffer())},{name:'00_Background.svg',data:backgroundSVGWithPaint()},{name:'01_K.svg',data:makeKSVG()},{name:'KyFold_Icon_1024.png',data:new Uint8Array(await full.arrayBuffer())},{name:'palette.json',data:projectText()},{name:'README.txt',data:'KyFold Color Studio 02.4\n\n原版高光现在可独立调整高光强度、颗粒保留量与颗粒强度。保留原版弧形；100% / 100% / 100% 恢复原版效果。较少颗粒主要降低颗粒疏密，连续亮带需通过高光强度调节。参数会保存到 palette.json 并应用于预览、SVG、PNG 和素材包。颗粒属于栅格细节层，透明 K SVG 只包含矢量高光。\n\n竖笔高光可选择原版或优化版。优化版用平滑、柔边的弧面反光替换旧亮带，保留可见高光，并可调节强度与高光颜色；仅影响竖笔，其余部位保留。选择已保存在 palette.json，并应用于 SVG、PNG 与素材包导出。\n\n所有导出均为 1024×1024 满版正方形，界面圆角仅用于预览。\n\n分层使用：00_Background.png（或 00_Background.svg 二选一）→ 01_K.svg → 02_Surface_Detail.png（如有）。SVG K 保留原矢量轮廓及折叠交接结构。\n\n画笔是栅格内容：已合成进背景 PNG；背景 SVG 通过内嵌 PNG 保留同样的模糊笔触。若目标软件不能导入带内嵌图像的 SVG，请使用背景 PNG。\n\nKyFold_Icon_1024.png 为当前完整合成预览，已包含开启的细颗粒；分层使用时不要再次叠加完整合成图。\n\npalette.json 可在此工具中重新导入，恢复颜色、位置、光场、背景及画笔。浏览器会尝试自动保存，重要配色请另存 JSON。\n\nIcon Composer 的实际材质与效果需要在本机核对；建议先关闭额外 Effects 检查导入素材。'}];if(state.detail)files.push({name:'02_Surface_Detail.png',data:await surfaceDetailBytes()});download(makeZip(files),'KyFold_Color_Assets.zip');toast('已打包 SVG、PNG、背景和可再次导入的配色。');}}catch(error){toast('导出未完成：'+error.message);}}
