function sanitize(data){const d=defaults(),color=(v,f)=>validHex(v||'')?v.toLowerCase():f,point=(v,f)=>({x:num(v?.x,0,100,f.x),y:num(v?.y,0,100,f.y)});if(data.version!==2){if(!Array.isArray(data.faces)||!data.faces.every(v=>validHex(v)))throw Error('不是可识别的 KyFold 配色文件');d.faces.forEach((f,i)=>{f.primary=color(data.faces[i],BASE);});d.background.stops[0].color=color(data.bgStart,d.background.stops[0].color);d.background.stops[2].color=color(data.bgEnd,d.background.stops[2].color);return d;}if(!Array.isArray(data.faces)||data.faces.length!==3)throw Error('配色需要包含三片 K');
 data.faces.forEach((f,i)=>{const out=d.faces[i];out.mode=['original','free','solid'].includes(f.mode)?f.mode:'original';out.primary=color(f.primary,BASE);out.white=color(f.white,'#ffffff');out.brightness=num(f.brightness,-70,70);out.count=Math.round(num(f.count,1,3,3));out.from=point(f.from,out.from);out.to=point(f.to,out.to);out.lightX=num(f.lightX,-50,50);out.lightY=num(f.lightY,-50,50);out.spread=num(f.spread,30,200,100);out.stops=out.stops.map((s,j)=>({color:color(f.stops?.[j]?.color,s.color),pos:num(f.stops?.[j]?.pos,0,100,s.pos)}));});
 const b=data.background||{},out=d.background;out.style=b.style==='free'?'free':'glass';out.count=Math.round(num(b.count,1,3,3));out.stops=out.stops.map((s,j)=>({color:color(b.stops?.[j]?.color,s.color),pos:num(b.stops?.[j]?.pos,0,100,s.pos)}));out.from=point(b.from,out.from);out.to=point(b.to,out.to);out.brightness=num(b.brightness,-70,70);out.brushColor=color(b.brushColor,out.brushColor);out.size=num(b.size,30,600,260);out.opacity=num(b.opacity,1,100,60);out.blur=num(b.blur,0,180,75);out.erase=!!b.erase;if(Array.isArray(b.strokes))out.strokes=b.strokes.slice(0,80).filter(s=>Array.isArray(s.points)&&s.points.length).map(s=>({color:color(s.color,'#4d89e6'),size:num(s.size,30,600,260),opacity:num(s.opacity,1,100,60),erase:!!s.erase,points:s.points.slice(0,1500).map(p=>({x:num(p.x,0,1024),y:num(p.y,0,1024)}))}));d.stemHighlight=data.stemHighlight==='soft'?'soft':'original';d.stemHighlightStrength=num(data.stemHighlightStrength,0,100,80);d.originalHighlightStrength=num(data.originalHighlightStrength,0,100,100);d.originalGrainDensity=num(data.originalGrainDensity,0,100,100);d.originalGrainStrength=num(data.originalGrainStrength,0,100,100);d.detail=data.detail!==false;d.folds=data.folds!==false;d.foldLines=Array.isArray(data.foldLines)?[0,1,2].map(i=>data.foldLines[i]!==false):[true,true,true];return d;}
